import random

def generate_fake_uid():
    prefixes = [17, 44, 178, 446, 1786, 4465, 17884, 44656]
    prefix = random.choice(prefixes)
    remaining_length = random.randint(7, 12)
    rest = ''.join([str(random.randint(0, 9)) for _ in range(remaining_length)])
    return int(f"{prefix}{rest}")

