# ==================== FRAME HEX ====================
JOIN_FRAME_HEX = ""

ONLINE_ROOM_HEX = ""

# ==================== BUILD ACCOUNTS ====================
ACCOUNTS = []

for token in YOUR_TOKENS:
    if not token or token.startswith("#"):
        continue
    
    fake_uid = generate_fake_uid()
    
    ACCOUNTS.append({
        "uid": fake_uid,
        "auth_token": token,
        "join_frame_hex": JOIN_FRAME_HEX,
        "online_room_frame_hex": ONLINE_ROOM_HEX
    })

# ==================== PRINT INFO ====================
print("\n" + "="*70)
print(f"📋 TOTAL {len(ACCOUNTS)} ACCOUNTS LOADED WITH FAKE UIDs")
print("="*70)
print("-" * 70)
for i, acc in enumerate(ACCOUNTS, 1):
    uid_len = len(str(acc["uid"]))
    fake_status = "🔴 FAKE" if (uid_len > 15 or uid_len < 10) else "🟢 REAL"
    print(f"Account {i:2d}: {fake_status}")
    print(f"  UID: {acc['uid']} (Length: {uid_len})")
    print(f"  Token: {acc['auth_token'][:50]}...")
    print("-" * 50)
print("="*70)
print(f"✅ Total {len(ACCOUNTS)} accounts ready!")
print("="*70 + "\n")
